"""Generate the static gallery and Forumactif CSS from the catalog source SVGs."""
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
import json
ICONS = [(i['name'], i['label'], i['category']) for i in json.loads((ROOT/'catalog.json').read_text())]
N=len(ICONS)
cards=[]
css=['/* Generated by scripts/build.py. URLs resolve relative to this stylesheet. */',
'.li { display:inline-block; width:1em; height:1em; background-color:currentColor; vertical-align:-.125em; -webkit-mask:var(--li-icon) center / contain no-repeat; mask:var(--li-icon) center / contain no-repeat; }']
for name,label,category in ICONS:
 variants=[]
 for style in ('outline','heraldic'):
  svg=(ROOT/f'icons/{style}/{name}.svg').read_text().strip()
  svg=svg.replace('<svg ', '<svg aria-hidden="true" focusable="false" ',1)
  variants.append(f'<section class="variant"><h3>{style}</h3>{svg}<button type="button" data-name="{name}" data-style="{style}">Copiar HTML</button><a href="./icons/{style}/{name}.svg" download="lannita-{name}-{style}.svg">Descargar SVG</a></section>')
  selector=f'.li-{name}' if style=='outline' else f'.li-heraldic.li-{name}'
  css.append(f'{selector} {{ --li-icon:url("../icons/{style}/{name}.svg"); }}')
 cards.append(f'<article data-search="{name} {label.lower()} {category.lower()}" data-category="{category}"><h2>{label} <code>{name}</code></h2><div class="pair">{"".join(variants)}</div></article>')
options=''.join(f'<option>{c}</option>' for c in sorted({c for _,_,c in ICONS}))
html='''<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Lannita Icons · Colección gratuita</title><meta name="description" content="Iconos SVG para rol medieval y fantasía. NUM símbolos editables en estilos outline y heraldic, listos para Foroactivo."><meta name="theme-color" content="#141416"><link rel="icon" type="image/svg+xml" href="./assets/brand/favicon.svg"><link rel="stylesheet" href="./css/gallery.css"><script src="./gallery.js" defer></script></head>
<body><header><p class="eyebrow">LANNITA CODES / RECURSOS GRATUITOS</p><h1 class="brand"><img src="./assets/brand/lannita-logo.svg" alt="Lannita Icons" width="460" height="140"></h1><div class="hero"><h2 class="hero-title">Pequeños símbolos.<br>Grandes historias.</h2><p>Iconos SVG para tus comunidades de rol medieval y fantasía. Editables, personalizables y listos para dar vida a tu foro.</p><div class="collection-meta"><span>NUM ICONOS</span><span>2 ESTILOS</span><span>OPEN SOURCE</span></div></div></header>
<div class="controls"><label>Buscar iconos<input id="search" type="search" placeholder="Corona, cuervo, key…"></label><label>Categoría<select id="category"><option value="">Todas las categorías</option>OPTIONS</select></label><label>Color<input id="color" type="color" value="#b48a3c"></label></div>
<p id="count" role="status">NUM iconos · VAR variantes</p><main>CARDS</main><p id="empty" hidden>No hay iconos con estos filtros.</p>
<p id="status" role="status" aria-live="polite"></p><dialog id="copy-fallback"><h2>Copia el HTML</h2><p>Selecciona y copia este SVG con Ctrl+C o ⌘C.</p><textarea aria-label="HTML del icono" readonly></textarea><form method="dialog"><button>Cerrar</button></form></dialog>
<footer><a href="./comparison.html">Comparativa de tamaños</a> · Outline: minimalista. Heraldic: sólido y ornamental. <a href="./README.md">Guía de uso y Foroactivo</a></footer></body></html>'''.replace('NUM',str(N)).replace('VAR',str(2*N)).replace('OPTIONS',options).replace('CARDS','\n'.join(cards))
(ROOT/'index.html').write_text(html)
(ROOT/'css/lannita-icons.css').write_text('\n'.join(css)+'\n')
print(f'Generated gallery: {N} icons, {2*N} variants; CSS: {2*N} mappings.')

rows=[]
for name,label,category in ICONS:
 cells=[]
 for style in ('outline','heraldic'):
  samples=[]
  for size in (16,24,32,64):
   svg=(ROOT/f'icons/{style}/{name}.svg').read_text().strip()
   # Isolate repeated mask IDs for every size and style in this document.
   import re
   for ident in re.findall(r'id="([^"]+)"',svg):
    svg=svg.replace(f'id="{ident}"',f'id="compare-{size}-{ident}"').replace(f'url(#{ident})',f'url(#compare-{size}-{ident})')
   svg=svg.replace('width="64" height="64" viewBox',f'width="{size}" height="{size}" viewBox',1)
   samples.append(f'<div class="sample">{svg}<small>{size}px</small></div>')
  cells.append(f'<section><h3>{style}</h3><div class="samples">{"".join(samples)}</div></section>')
 rows.append(f'<article><h2>{label} <code>{name}</code></h2><div class="compare-pair">{"".join(cells)}</div></article>')
(ROOT/'comparison.html').write_text('<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Lannita Icons · Comparativa</title><link rel="stylesheet" href="./css/gallery.css"><style>main{display:block}article{margin:16px 0}.compare-pair{display:grid;grid-template-columns:1fr 1fr;gap:24px}.samples{display:flex;align-items:end;gap:24px;min-height:100px}.sample{display:grid;justify-items:center;gap:12px;color:#b48a3c}.sample small{color:#aaa497}.samples svg{display:block}section{padding:16px;background:#141416}@media(max-width:600px){.compare-pair{grid-template-columns:1fr}.samples{gap:20px}}</style></head><body><a href="./index.html">Volver a la galería</a><h1>'+str(N)+' símbolos, dos estilos.</h1><p>Comparativa de los '+str(2*N)+' SVG a 16, 24, 32 y 64 píxeles.</p><main>'+''.join(rows)+'</main></body></html>')
